 if(s.startsWith('ألعاب وتدريبات الوحدة ')){const n=ordinals[s.slice('ألعاب وتدريبات الوحدة '.length)];if(n)return 'Unit '+n+' games and practice';}

 if(/^[٠-٩]+$/.test(s))return digits(s);
