 if(s.includes(' · ')){const parts=s.split(' · ');const mapped=parts.map(english);if(mapped.some((x,i)=>x!==parts[i]))return mapped.join(' · ');}
 if(s.startsWith('شرح الوحدة '))return 'Unit '+digits(s.slice('شرح الوحدة '.length))+' lesson';
 if(s.startsWith('شرح المراجعة '))return 'Revision '+digits(s.slice('شرح المراجعة '.length))+' lesson';
 const simpleGrades={'أول ابتدائي':'Primary 1','ثاني ابتدائي':'Primary 2','ثالث ابتدائي':'Primary 3','رابع ابتدائي':'Primary 4','خامس ابتدائي':'Primary 5','سادس ابتدائي':'Primary 6','أول متوسط':'Intermediate 1','ثاني متوسط':'Intermediate 2','أولى حضانة':'Kindergarten 1','تانية حضانة':'Kindergarten 2','تالتة ابتدائي':'Primary 3','رابعة ابتدائي':'Primary 4'};
 for(const [a,b] of Object.entries(simpleGrades)){if(s===a)return b;if(s.startsWith(a+' '))return b+s.slice(a.length);}
