 if(s.startsWith('منهج '))return english(s.slice(5))+' curriculum';
 if(s.startsWith('فتح التنقل السريع: '))return 'Open quick navigation: '+english(s.slice('فتح التنقل السريع: '.length));
 if(s.startsWith('إغلاق التنقل السريع: '))return 'Close quick navigation: '+english(s.slice('إغلاق التنقل السريع: '.length));
